{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/activation_review.py; .github/workflows/cloud-pilot-manual.yml",
      "detail": "The code-review packet reads the reusable workflow from the checked-out code tree, but the caller executes cloud-pilot-trusted.yml at a separate pinned commit. The supplied files do not establish that those are the same bytes. Runtime permit checks authenticate a workflow hash but do not bind the independently reviewed local workflow to the pinned executable workflow.",
      "required_fix": "Fetch the caller and reusable workflow at their actual pinned revisions, include their exact contents and hashes in the independent code-review packet, and bind the receipt and permit to those hashes."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/stages.py; cloud_pilot/multilingual/research_contract.py",
      "detail": "The current-standard gate runs only when a fact has kind='standard', but the active research contract accepts only external_fact or editorial_method. Consequently, a standard-related fact accepted by the active contract cannot trigger the required version, amendment, effective-date and primary-source checks. The existing standard test uses a topic outside the active contract.",
      "required_fix": "Represent standard classification separately from external fact versus editorial method, enforce the complete current-standard gate for applicable facts, and add regression tests using both active article types."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/research_contract.py",
      "detail": "Vehicle identity fields can be marked VERIFIED with any known source ID, including a T3 source, without checking primary authority, matched scope or direct support for that identity field. Quantitative allowed facts are also not required by validation to contain the value and unit requested by the contract. Independent model review does not repair these missing structural gates.",
      "required_fix": "Bind every identity field and quantitative fact to scoped, directly supporting evidence; enforce fact-level confidence rules, value and unit requirements, and block writing when a core identity field is unresolved."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/research_contract.py; cloud_pilot/live/engine.py",
      "detail": "The handoff requires only that locks be a list; neither validation nor the writing transition checks explicit RESEARCH_LOCK or WRITING_LOCK states. A handoff containing an active research lock can therefore proceed to writing, contrary to ARTICLE_STATUS_LOCK.",
      "required_fix": "Represent and validate explicit lock and update-required fields, prevent writing while research is locked or has changed, and re-read the fresh fact baseline before resuming."
    },
    {
      "severity": "high",
      "file": ".github/workflows/cloud-pilot-manual.yml; cloud_pilot/multilingual/authorization.py",
      "detail": "The caller forwards secret-context values before the reusable workflow's environment approval and runtime workflow checks. If those values are repository or organization secrets visible to the caller, a changed dispatchable caller could expose them in another job before preauthorization; checking the caller afterward cannot prevent that exposure. The supplied files do not establish the secrets' actual scope.",
      "required_fix": "Verify and enforce environment-only project credentials, restrict modification and dispatch of the caller, and ensure no caller-accessible credential can be used before the protected job and approval checks."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/startup.py; cloud_pilot/live/stages.py",
      "detail": "Review-handoff selection relies on filename groups and a global latest date rather than classifying applicability. A relevant handoff can be omitted when another selected handoff is later. Separately, check_writing records skill_impact_check_done=true and skill_update_required=false without performing that assessment.",
      "required_fix": "Discover and classify applicable handoffs for the approved topics and baseline, bind the selected contents to the run, and perform and record an actual writing-side skill-impact assessment rather than hard-coding its result."
    },
    {
      "severity": "medium",
      "file": "cloud_pilot/multilingual/localize.py",
      "detail": "Locale review receives markdown rendered with public_only=true, while delivery writes markdown with public_only=false, adding metadata labels and editorial text that were not part of that rendered review. The bundle nevertheless reports twenty-four text drafts reviewed, without binding the review to the exact delivered Markdown bytes.",
      "required_fix": "Review and hash the exact delivered locale artifact, or deliver the reviewed public rendering separately and explicitly mark all unreviewed components incomplete."
    },
    {
      "severity": "medium",
      "file": "cloud_pilot/stage2_tests/test_live.py; cloud_pilot/evidence/activation/recovery-stage2-tests.txt; cloud_pilot/runtime/multilingual-manual.yml.template",
      "detail": "The reported passing stage-two test asserts that the template equals the installed manual workflow, but the supplied files differ in both the pinned reusable-workflow SHA and secret forwarding. That passing log therefore cannot substantiate the supplied candidate.",
      "required_fix": "Reconcile the template and test with the intended workflow, rerun the complete offline suite against the exact candidate SHA, and retain fresh results."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
